INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist TCP/IP nur für das Internet nötig?', 2, '[{"text": "Nein", "correct": true, "because": "Auch in lokalen Netzwerken verwendet"}, {"text": "Ja", "correct": false, "because": "Nicht auf Internet beschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Protokoll wähle ich für zuverlässige Datenübertragung?', 3, '[{"text": "TCP", "correct": true, "because": "Gewährleistet Paketzustellung"}, {"text": "UDP", "correct": false, "because": "Schnell, aber unzuverlässig"}, {"text": "OSPF", "correct": false, "because": "Routing, nicht Übertragung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen OSPF für große Netzwerke geeignet?', 5, '[{"text": "Dynamisches Routing", "correct": true, "because": "Passt sich Änderungen an"}, {"text": "Link-State-Algorithmus", "correct": true, "because": "Effiziente Routenberechnung"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Hardwareabhängig"}, {"text": "Einfache Konfiguration", "correct": false, "because": "Komplexer als statisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) VLANs trennen Netzwerke physisch. b) TCP garantiert Reihenfolge.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "a) ist falsch, VLANs sind logisch"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Wahl eines Protokolls für Streaming?', 4, '[{"text": "Geschwindigkeit", "correct": false, "because": "Kritisch für Echtzeit"}, {"text": "Zuverlässigkeit", "correct": false, "because": "Wichtig bei schlechten Netzen"}, {"text": "Routing-Komplexität", "correct": true, "because": "OSPF ist hier irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob OSPF in kleinen Netzwerken sinnvoll ist?', 2, '[{"text": "Nein", "correct": true, "because": "Zu komplex für wenige Geräte"}, {"text": "Ja", "correct": false, "because": "Statisches Routing reicht oft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature priorisiere ich für ein VLAN?', 3, '[{"text": "Netzwerksegmentierung", "correct": true, "because": "Trennt Traffic logisch"}, {"text": "Hohe Latenz", "correct": false, "because": "Nicht gewünscht"}, {"text": "Physische Trennung", "correct": false, "because": "Logisch, nicht physisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet TCP/IP?', 5, '[{"text": "Zuverlässigkeit", "correct": true, "because": "TCP stellt Pakete sicher"}, {"text": "Universelle Nutzung", "correct": true, "because": "Standard im Internet"}, {"text": "Einfache Einrichtung", "correct": false, "because": "Kann komplex sein"}, {"text": "Hohe Geschwindigkeit", "correct": false, "because": "UDP ist schneller"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) VLANs erhöhen die Sicherheit. b) OSPF ist ein Übertragungsprotokoll. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, OSPF ist Routing"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein Protokoll bei Videokonferenzen?', 4, '[{"text": "Niedrige Latenz", "correct": false, "because": "Wichtig für Echtzeit"}, {"text": "Stabile Verbindung", "correct": false, "because": "Notwendig für Qualität"}, {"text": "Komplexes Routing", "correct": true, "because": "OSPF überflüssig bei einfachen Setups"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist UDP schneller als TCP?', 2, '[{"text": "Ja", "correct": true, "because": "Keine Bestätigungen nötig"}, {"text": "Nein", "correct": false, "because": "TCP ist zuverlässiger, aber langsamer"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften sind für VLANs in einem Büro wichtig?', 4, '[{"text": "Traffic-Trennung", "correct": true, "because": "Abteilungen isolieren"}, {"text": "Sicherheit", "correct": true, "because": "Zugriff einschränken"}, {"text": "Physische Kabel", "correct": false, "because": "Logische Trennung"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass TCP/IP nur auf Schicht 3 arbeitet. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "TCP ist Schicht 4, IP Schicht 3"}, {"text": "Ja", "correct": false, "because": "Mehrere Schichten betroffen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich für ein Routing-Protokoll in einem Campus-Netzwerk?', 3, '[{"text": "Schnelle Konvergenz", "correct": true, "because": "OSPF reagiert schnell"}, {"text": "Einfache Einrichtung", "correct": false, "because": "Sekundär"}, {"text": "Minimale Bandbreite", "correct": false, "because": "Leistung zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) OSPF nutzt Link-State. b) VLANs benötigen eigene Switches.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, ein Switch reicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat TCP?', 5, '[{"text": "Höhere Latenz", "correct": true, "because": "Bestätigungen kosten Zeit"}, {"text": "Overhead", "correct": true, "because": "Mehr Datenverkehr"}, {"text": "Geringere Zuverlässigkeit", "correct": false, "because": "TCP ist zuverlässig"}, {"text": "Komplexe Einrichtung", "correct": false, "because": "Standardmäßig einfach"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Protokoll für IoT-Geräte unwichtig?', 3, '[{"text": "Geringer Overhead", "correct": false, "because": "Wichtig für kleine Geräte"}, {"text": "Effizienz", "correct": false, "because": "Kritisch für Batterie"}, {"text": "Komplexes Routing", "correct": true, "because": "OSPF überflüssig bei Simplen"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Arbeitet OSPF auf Schicht 2?', 3, '[{"text": "Nein", "correct": true, "because": "Schicht 3, Routing-Protokoll"}, {"text": "Ja", "correct": false, "because": "Verwechselt mit Switching"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob VLANs die Bandbreite erhöhen?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Trennung, keine Erhöhung"}, {"text": "Ja", "correct": false, "because": "Bandbreite bleibt gleich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Protokoll wähle ich für ein kleines Heimnetzwerk?', 4, '[{"text": "TCP/IP", "correct": true, "because": "Universell und ausreichend"}, {"text": "OSPF", "correct": false, "because": "Zu komplex"}, {"text": "VLAN", "correct": false, "because": "Nicht primär nötig"}]');
